def pricing(cc):
    cc = cc.lower()
    return dict(name='VRITIMES', title=f'Pricing page ({cc.upper()}) — PRICE_UNVERIFIED in this run', year=2026,
                url=f'https://www.vritimes.com/{cc}/service/pricing', short=f'vritimes.com/{cc}/service/pricing')
def service(cc):
    cc = cc.lower()
    return dict(name='VRITIMES', title=f'Service page ({cc.upper()})', year=2026,
                url=f'https://www.vritimes.com/{cc}/service', short=f'vritimes.com/{cc}/service')
def get(key, cc):
    if key == 'PRICE': return pricing(cc)
    if key == 'SERVICE': return service(cc)
    return S[key]
